type EditorialCarrosselDeCitacoesProps = {
  className?: string;
  voz?: "Mariazinha Baré" | "Neideana Ribeiro";
};

function EditorialCarrosselDeCitacoes({ className, voz = "Mariazinha Baré" }: EditorialCarrosselDeCitacoesProps) {
  const isMariazinhaBare = voz === "Mariazinha Baré";
  const isNeideanaRibeiro = voz === "Neideana Ribeiro";
  return (
    <div className={className || "bg-[var(--margem-cor-verde,#153b2e)] content-stretch flex flex-col gap-[8px] h-[283px] items-start px-[24px] py-[16px] relative rounded-[8px] w-[1344px]"} id={isNeideanaRibeiro ? "node-50_151" : "node-50_141"}>
      <p className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[24px] relative shrink-0 text-[16px] text-[color:var(--margem-cor-lima,#d5e74e)] w-[1296px]" id={isNeideanaRibeiro ? "node-50_152" : "node-50_142"} style={{ fontVariationSettings: '"wdth" 100' }}>
        VOZES DA PESQUISA / ENTREVISTAS PUBLICADAS
      </p>
      <p className="[word-break:break-word] font-['Libre_Baskerville:Regular'] font-normal leading-[43px] relative shrink-0 text-[32px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[1296px]" id={isNeideanaRibeiro ? "node-50_153" : "node-50_143"}>
        {isNeideanaRibeiro ? "“O Brasil sai do Mapa da Fome, mas a região Norte é uma região ainda muito vulnerabilizada.”" : "“A navegabilidade melhorou em algumas regiões, mas a questão da insegurança alimentar e a falta de água potável permanecem.”"}
      </p>
      <p className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[24px] relative shrink-0 text-[16px] text-[color:var(--margem-cor-lima,#d5e74e)] w-[1296px]" id={isNeideanaRibeiro ? "node-50_154" : "node-50_144"} style={{ fontVariationSettings: '"wdth" 100' }}>
        {isNeideanaRibeiro ? "NEIDEANA RIBEIRO • UNICEF" : "MARIAZINHA BARÉ • APIAM"}
      </p>
      <p className="[word-break:break-word] font-['Archivo:Regular'] font-normal leading-[24px] relative shrink-0 text-[16px] text-[color:var(--margem-cor-papel,#f2efdf)] w-[1296px]" id={isNeideanaRibeiro ? "node-50_155" : "node-50_145"} style={{ fontVariationSettings: '"wdth" 100' }}>
        {isNeideanaRibeiro ? "Entrevista de Jhonny Lima / A Crítica, 05/10/2025 • “Fome: ‘Norte é uma região ainda muito vulnerável’.”" : "Entrevista publicada por Murilo Pajolla / Brasil de Fato, 19/01/2024."}
      </p>
      <div className="content-stretch flex gap-[16px] h-[36px] items-start overflow-clip relative shrink-0 w-[1296px]" id={isNeideanaRibeiro ? "node-50_156" : "node-50_146"} data-name="Escolha da citação">
        {isMariazinhaBare && (
          <>
            <div className="bg-[var(--margem-cor-lima,#d5e74e)] border border-[var(--margem-cor-lima,#d5e74e)] border-solid content-stretch flex h-[36px] items-center justify-center overflow-clip p-[6px] relative rounded-[18px] shrink-0 w-[272px]" data-node-id="50:147" data-name="Ler Mariazinha Baré">
              <p className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[24px] relative shrink-0 text-[16px] text-[color:var(--margem-cor-verde,#153b2e)] w-[240px]" data-node-id="50:148" style={{ fontVariationSettings: '"wdth" 100' }}>
                01 / Mariazinha Baré
              </p>
            </div>
            <button className="bg-[var(--margem-cor-verde,#153b2e)] border border-[var(--margem-cor-lima,#d5e74e)] border-solid content-stretch cursor-pointer flex h-[36px] items-center justify-center overflow-clip p-[6px] relative rounded-[18px] shrink-0 w-[272px]" data-node-id="50:149" data-name="Ler Neideana Ribeiro">
              <div className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[0] relative shrink-0 text-[16px] text-[color:var(--margem-cor-papel,#f2efdf)] text-left w-[240px]" data-node-id="50:150" role="button" style={{ fontVariationSettings: '"wdth" 100' }} tabIndex="0">
                <p className="leading-[24px]">02 / Neideana Ribeiro</p>
              </div>
            </button>
          </>
        )}
        {isNeideanaRibeiro && (
          <>
            <button className="bg-[var(--margem-cor-verde,#153b2e)] border border-[var(--margem-cor-lima,#d5e74e)] border-solid content-stretch cursor-pointer flex h-[36px] items-center justify-center overflow-clip p-[6px] relative rounded-[18px] shrink-0 w-[272px]" data-node-id="50:157" data-name="Ler Mariazinha Baré">
              <div className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[0] relative shrink-0 text-[16px] text-[color:var(--margem-cor-papel,#f2efdf)] text-left w-[240px]" data-node-id="50:158" role="button" style={{ fontVariationSettings: '"wdth" 100' }} tabIndex="0">
                <p className="leading-[24px]">01 / Mariazinha Baré</p>
              </div>
            </button>
            <div className="bg-[var(--margem-cor-lima,#d5e74e)] border border-[var(--margem-cor-lima,#d5e74e)] border-solid content-stretch flex h-[36px] items-center justify-center overflow-clip p-[6px] relative rounded-[18px] shrink-0 w-[272px]" data-node-id="50:159" data-name="Ler Neideana Ribeiro">
              <p className="[word-break:break-word] font-['Archivo:Bold'] font-bold leading-[24px] relative shrink-0 text-[16px] text-[color:var(--margem-cor-verde,#153b2e)] w-[240px]" data-node-id="50:160" style={{ fontVariationSettings: '"wdth" 100' }}>
                02 / Neideana Ribeiro
              </p>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
